export type EngineEvent = { type: "PlaybackStateChanged"; payload: { state: PlaybackState } } | { type: "TrackChanged"; payload: { track: TrackSummary | null; palette: CoverPalette; queue_index: number | null; duration_ms: number } } | { type: "QueueUpdated"; payload: { queue: TrackSummary[]; queue_index: number | null } } | { type: "FormatNegotiated"; payload: { format: StreamFormatInfo } } | { type: "DevicesEnumerated"; payload: { devices: AudioDeviceDescriptor[] } } | { type: "LibrarySynced"; payload: { payload: LibrarySyncPayload } } | { type: "PreferencesUpdated"; payload: { preferences: AppPreferences } } | { type: "AuthChanged"; payload: { authenticated: boolean; user_id: number | null; country_code: string | null } } | { type: "ErrorBanner"; payload: { message: string } } | { type: "StatusBanner"; payload: { message: string } } | { type: "TrayAction"; payload: { action: TrayUiAction } }
export type EngineEventNotice = EngineEvent
/**
 * Données dynamiques de l'onglet **Explorer** chargées depuis les endpoints TIDAL officiels
 * (OpenAPI v2 `userNewReleaseMixes`, `userDiscoveryMixes`, `userDailyMixes`, `searchResults` + pages catalogue).
 */
export type ExploreHubData = { spotlight_albums: AlbumSummary[]; featured_playlists: PlaylistSummary[]; new_release_tracks: TrackSummary[]; discovery_tracks: TrackSummary[]; 
/**
 * Miniatures réelles indexées par nom de catégorie ou genre (`"Nouveautés"`, `"Hip-Hop"`, etc.).
 */
category_covers: Partial<{ [key in string]: string }> }
export type HybridSearchResults = { seq: number; query: string; local_tracks: TrackSummary[]; remote: SearchResults }
export type LastFmStatus = { connected: boolean; username: string | null; enabled: boolean }
export type LibrarySyncPayload = { favorites: TrackSummary[]; favorite_ids: number[]; playlists: PlaylistSummary[]; playlist_folders: PlaylistFolder[]; favorite_albums: AlbumSummary[]; favorite_album_ids: number[]; favorite_artists: ArtistSummary[]; favorite_artist_ids: number[]; user_mixes: MixSummary[]; discover_tracks: TrackSummary[] }
/**
 * Statistiques locales « Mon Activité » calculées depuis SQLite.
 */
export type ListeningActivityStats = { total_plays: number; total_secs: number; plays_last_30_days: number; secs_last_30_days: number; unique_artists: number; top_tracks: ActivityTrackStat[]; top_artists: ActivityArtistStat[]; recent_plays: TrackSummary[] }
/**
 * Une ligne de paroles synchronisées au format LRC.
 */
export type LyricsLine = { 
/**
 * Horodatage de la ligne, en millisecondes depuis le début du titre.
 */
time_ms: number; text: string }
/**
 * Carte de mix personnalisé TIDAL (Daily Mix, Découverte, Nouveautés...).
 */
export type MixSummary = { id: string; title: string; subtitle: string; image_id: string | null; tracks: TrackSummary[] }
/**
 * Format d'un flux PCM décodé (échantillons internes normalisés en `i32` alignés
 * MSB ou valeur signée `bits_per_sample`).
 */
export type PcmFormat = { 
/**
 * Fréquence d'échantillonnage en Hz (`44100`, `48000`, `88200`, `96000`, `176400`, `192000`).
 */
sample_rate: number; 
/**
 * Nombre de canaux (`2` pour la stéréo).
 */
channels: number; 
/**
 * Profondeur de bits réelle du flux décodé (`16`, `24` ou `32`).
 */
bits_per_sample: number }
/**
 * État courant du moteur de lecture.
 */
export type PlaybackState = "Stopped" | "Buffering" | "Playing" | "Paused" | { Error: string }
export type PlaylistDetailData = { playlist: PlaylistSummary; tracks: TrackSummary[]; tidal_indices: number[] }
export type PlaylistExportFormat = "Csv" | "M3u8"
export type PlaylistExportPayload = { filename: string; content: string; mime_type: string }
/**
 * Dossier de playlists TIDAL regroupant plusieurs playlists.
 */
export type PlaylistFolder = { id: string; name: string; total_number_of_items?: number; playlists?: PlaylistSummary[] }
export type PlaylistImportResult = { playlist: PlaylistSummary; imported_count: number; unmatched: string[] }
/**
 * Résumé d'une playlist TIDAL.
 */
export type PlaylistSummary = { uuid: string; title: string; description: string | null; creator: string; number_of_tracks: number; image_id: string | null }
/**
 * Mode de répétition de la file d'attente.
 */
export type RepeatMode = "Off" | "All" | "One"
/**
 * Mode de normalisation ReplayGain sans perte (protection crête 0 dBFS incluse).
 */
export type ReplayGainMode = "Off" | "Track" | "Album"
/**
 * Résultats consolidés d'une recherche catalogue TIDAL.
 */
export type SearchResults = { tracks: TrackSummary[]; albums: AlbumSummary[]; playlists: PlaylistSummary[]; artists: ArtistSummary[]; top_hit?: TopHit | null }
/**
 * Suggestions instantanées d'autocomplétion (requêtes + résultats directs).
 */
export type SearchSuggestions = { queries: string[]; tracks: TrackSummary[]; albums: AlbumSummary[]; artists: ArtistSummary[] }
/**
 * Métadonnées complètes du pipeline audio actif (affichées dans la barre de lecture).
 */
export type StreamFormatInfo = { 
/**
 * Codec source (`"FLAC"`, `"AAC"`, etc.).
 */
codec: string; 
/**
 * Format PCM issu du décodeur.
 */
source_pcm: PcmFormat; 
/**
 * Profondeur de bits du conteneur matériel WASAPI négocié avec le DAC (`16`, `24` ou `32`).
 */
dac_container_bits: number; 
/**
 * Bits valides acceptés par le DAC (`16`, `24` ou `32`).
 */
dac_valid_bits: number; 
/**
 * `true` si `IAudioClient` tourne en `AUDCLNT_SHAREMODE_EXCLUSIVE`.
 */
is_exclusive: boolean; 
/**
 * `true` si aucun rééchantillonnage ni atténuation logicielle n'est appliqué.
 */
is_bit_perfect: boolean; 
/**
 * Nom du périphérique WASAPI actif.
 */
device_name: string }
/**
 * Meilleur résultat mis en avant lors d'une recherche catalogue (`topHit` v1 / `topHits` OpenAPI v2).
 */
export type TopHit = { kind: "Track"; value: TrackSummary } | { kind: "Album"; value: AlbumSummary } | { kind: "Artist"; value: ArtistSummary } | { kind: "Playlist"; value: PlaylistSummary }
/**
 * Groupe de contributeurs d'un même rôle (production, mixage, écriture...).
 */
export type TrackCreditGroup = { role: string; contributors: string[] }
/**
 * Crédits complets d'un titre TIDAL, regroupés par rôle.
 */
export type TrackCredits = { track_id: number; groups: TrackCreditGroup[] }
/**
 * Paroles d'un titre TIDAL : texte brut et/ou lignes synchronisées LRC.
 */
export type TrackLyrics = { track_id: number; plain_text: string | null; synced_lines: LyricsLine[]; provider: string | null }
/**
 * Résumé d'un titre du catalogue TIDAL (optimisé pour le cache SQLite et les listes virtualisées).
 */
export type TrackSummary = { id: number; title: string; artist_name: string; 
/**
 * Identifiant TIDAL de l'artiste principal (facultatif, absent des anciens snapshots).
 */
artist_id?: number | null; album_id?: number | null; album_title: string; 
/**
 * UUID de pochette TIDAL (`xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx`).
 */
cover_id: string | null; duration_secs: number; audio_quality: string | null; explicit: boolean; dolby_audio?: boolean }
export type TrayUiAction = "ShowWindow" | "QuitApp"
/**
 * Police de caractères de l'interface utilisateur.
 */
export type UiFontFamily = 
/**
 * Police actuelle par défaut (Inter / Segoe UI Variable).
 */
"Default" | 
/**
 * Season Mix (Displaay).
 */
"SeasonMix" | 
/**
 * DM Sans.
 */
"DmSans" | 
/**
 * Plus Jakarta Sans.
 */
"PlusJakartaSans"

/** tauri-specta globals **/

import {
	invoke as TAURI_INVOKE,
	Channel as TAURI_CHANNEL,
} from "@tauri-apps/api/core";
import * as TAURI_API_EVENT from "@tauri-apps/api/event";
import { type WebviewWindow as __WebviewWindow__ } from "@tauri-apps/api/webviewWindow";

type __EventObj__<T> = {
	listen: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.listen<T>>;
	once: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.once<T>>;
	emit: null extends T
		? (payload?: T) => ReturnType<typeof TAURI_API_EVENT.emit>
		: (payload: T) => ReturnType<typeof TAURI_API_EVENT.emit>;
};

export type Result<T, E> =
	| { status: "ok"; data: T }
	| { status: "error"; error: E };

function __makeEvents__<T extends Record<string, any>>(
	mappings: Record<keyof T, string>,
) {
	return new Proxy(
		{} as unknown as {
			[K in keyof T]: __EventObj__<T[K]> & {
				(handle: __WebviewWindow__): __EventObj__<T[K]>;
			};
		},
		{
			get: (_, event) => {
				const name = mappings[event as keyof T];

				return new Proxy((() => {}) as any, {
					apply: (_, __, [window]: [__WebviewWindow__]) => ({
						listen: (arg: any) => window.listen(name, arg),
						once: (arg: any) => window.once(name, arg),
						emit: (arg: any) => window.emit(name, arg),
					}),
					get: (_, command: keyof __EventObj__<any>) => {
						switch (command) {
							case "listen":
								return (arg: any) => TAURI_API_EVENT.listen(name, arg);
							case "once":
								return (arg: any) => TAURI_API_EVENT.once(name, arg);
							case "emit":
								return (arg: any) => TAURI_API_EVENT.emit(name, arg);
						}
					},
				});
			},
		},
	);
}
